questionvariables.text:
cement_scale: 10;
cement_steps: rand(100*cement_scale/10 + 1);
cement: float(20 + cement_steps/cement_scale);
cement_err: float(0.5/cement_scale);

sand_scale: 10;
sand_steps: rand(200*sand_scale/10 + 1);
sand: float(50 + sand_steps/sand_scale);
sand_err: float(0.5/sand_scale);

max_cement: cement + cement_err;
min_cement: cement - cement_err;

max_sand: sand + sand_err;
min_sand: sand - sand_err;

ratio: float(sand / cement);
max_ratio: float(max_sand / min_cement);
min_ratio: float(min_sand / max_cement);

ta1: max_ratio - ratio;
ta2: ta1 / ratio;
ta3: ta2 * 100;
